style.css:
@-moz-document domain("pinterest.com"), domain("www.pinterest.com") {
@font-face {
    font-family: 'Hachi Maru Pop';
    font-style: normal;
    font-weight: 400;
    src: url('https://fonts.gstatic.com/s/hachimaru/v15/yYLx0hXQEFjGG7QxXzEwrQ.woff2') format('woff2');
  }

  body {
    background-color: #FFF8E7 !important; /* giallo crema */
    color: #4B3B2B !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }

  /* Non cambiamo il background dei contenitori per non nascondere immagini */
  /* Cambiamo solo il background delle aree di testo e pulsanti */

  /* Esempio: area header, sidebar, footer (se presenti) */
  header, nav, footer, aside {
    background-color: #FFE4E9 !important; /* rosa pastello */
  }

  /* Pulsanti */
  button, .Button, .btn {
    background-color: #FADADD !important;
    color: #4B3B2B !important;
    border-radius: 8px !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }

  /* Link */
  a {
    color: #E8A87C !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }

  /* Titoli */
  h1, h2, h3, h4, h5, h6 {
    color: #4B3B2B !important;
    font-family: 'Hachi Maru Pop', cursive !important;
  }

  /* Assicuriamoci che immagini e pin siano visibili */
  img, picture, svg {
    background: transparent !important;
    visibility: visible !important;
  }
}
